import csv
import io
import re

_INT_RE = re.compile(r'^[+-]?\d+$')
_FLOAT_RE = re.compile(r'^[+-]?(\d+\.\d*|\.\d+|\d+)([eE][+-]?\d+)?$')


def _infer(value):
    if value in ('null', 'None'):
        return None
    if value == 'true':
        return True
    if value == 'false':
        return False
    # Leading zeros (e.g. '007') must stay strings; also reject bare '-'/'+'.
    if _INT_RE.match(value) and not (len(value.lstrip('+-')) > 1 and value.lstrip('+-')[0] == '0'):
        return int(value)
    if _FLOAT_RE.match(value):
        stripped = value.lstrip('+-')
        # Reject pure-integer floats with leading zeros like '007.5' -> keep string.
        mantissa = stripped.split('e')[0].split('E')[0]
        if '.' in mantissa:
            digits = mantissa.replace('.', '').lstrip('0')
            whole = mantissa.split('.')[0].lstrip('+-')
            if len(whole) > 1 and whole[0] == '0':
                return value  # leading zero in integer part -> string
            if digits == '':
                return 0.0 if float(value) == 0 else value
            return float(value)
        else:
            # Exponent-only form like '1e5' is fine; leading-zero ints already handled.
            return float(value)
    return value


def parse_csv_typed(csv_string):
    reader = csv.reader(io.StringIO(csv_string))
    rows = [row for row in reader if any(cell.strip() != '' for cell in row)]
    if not rows:
        return []
    header = [h.strip() for h in rows[0]]
    result = []
    for row in rows[1:]:
        # Pad or trim row to match header length
        row = row + [''] * (len(header) - len(row))
        record = {}
        for key, raw in zip(header, row):
            record[key] = _infer(raw.strip())
        result.append(record)
    return result
